-- pipeline/candidates
-- One page of likely crash news waiting for a reviewer, newest first, with the total for the pager.
--
-- Parameters, with the example values used to render this file:
--   $1 = true
--   $2 = "new"
--   $3 = 20
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

select "feed_items"."id", "feed_items"."title", "feed_items"."url", "feed_items"."summary", "feed_items"."published_at", "feed_items"."seen_at", "feed_items"."matched_terms", "outlets"."name", count(*) over ()
from "feed_items"
inner join "outlets" on "outlets"."id" = "feed_items"."outlet_id"
where ("feed_items"."matched" = $1
  and "feed_items"."status" = $2)
order by coalesce("feed_items"."published_at", "feed_items"."seen_at") desc, "feed_items"."id" desc
limit $3;
